/* Human incident workflow for management and a small driver view. */
 const N=globalThis.RodavoltIncidents;
 function incidentsPanel(){const records=N.list(ops).slice().reverse();return panel('Multas, sinistros e avarias',`<p class="caption">Registre o ocorrido, acompanhe prazos e ouça o motorista. O valor proposto não é dívida. A responsabilidade e o custo exigem decisão humana, sem desconto automático de caução.</p>${table(['Ocorrência','Motorista e carro','Prazo','Situação','Ação'],records.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${N.types.find(([k])=>k===r.type)?.[1]} · ${date(r.date)} · ${esc(r.id)}</small></td><td>${esc(r.driverName)}<small>${esc(r.vehicleId)} · ciclo ${r.deliveryCycle+1}</small></td><td>${date(r.deadline)}</td><td>${tag(N.statuses[r.status],r.status==='resolved'?'green':'amber')}${r.decision?`<small>${esc(N.responsibilities[r.decision.responsibility])} · ${cash(r.decision.approvedAmount)}</small>`:''}</td><td>${btn('Acompanhar','incident-open','',`data-id="${r.id}"`)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhuma ocorrência nesta sessão.</td></tr>')}`,btn('Registrar ocorrência','incident-new'));}
 function incidentCreateForm(){const active=ops.drivers.filter(d=>d.stage==='active'&&d.vehicleId);return `<form id="incident-create-form"><div class="fields">${select('driverId','Motorista do vínculo','', [['','Escolha o motorista'],...active.map(d=>[d.id,d.name+' · '+d.vehicleId])],'required')}${select('type','Tipo','fine',N.types)}${input('date','Data do ocorrido',K.operatingDate,'type="date" required')}${input('deadline','Prazo de acompanhamento',K.operatingDate,'type="date" required')}${input('title','Título resumido','','required maxlength="120"')}${input('proposedAmount','Valor proposto · opcional, ainda sem aprovação','','type="number" min="0" step="0.01"')}${input('reference','Referência da ocorrência · opcional','','maxlength="100"')}${input('evidenceReference','Código de referência da evidência futura · sem arquivos pessoais','','maxlength="150"')}${input('insuranceReference','Referência interna do seguro · opcional','','maxlength="150"')}</div><label class="field gap">Descrição que o motorista poderá ler<textarea name="description" required rows="3" maxlength="1500"></textarea></label><label class="check gap"><input name="unavailable" type="checkbox">O carro está indisponível: abrir ou vincular uma manutenção.</label><p class="caption gap">Nenhuma multa é consultada ou enviada a órgãos externos. A referência não armazena documentos ou imagens. No sistema final, anexos serão privados.</p><div class="form-actions"><button class="btn primary" type="submit">Registrar para análise</button></div></form>`;}
 function incidentDetail(id){const r=N.lookup(ops,id);return row('Ocorrência',esc(r.id)+' · '+esc(N.types.find(([k])=>k===r.type)?.[1]))+row('Motorista e carro',esc(r.driverName)+' · '+esc(r.vehicleId),'Ciclo '+(r.deliveryCycle+1))+row('Data e prazo',date(r.date)+' → '+date(r.deadline))+row('Situação',tag(N.statuses[r.status],r.status==='resolved'?'green':'amber'))+`<p>${esc(r.description)}</p>`+(r.proposedAmount!==null?row('Valor somente proposto',cash(r.proposedAmount),'Ainda não é cobrança nem decisão.'):'')+(r.evidenceReference?row('Referência privada futura',esc(r.evidenceReference),'Somente código; não há anexo armazenado.'):'')+(r.insuranceReference?row('Referência interna de seguro',esc(r.insuranceReference)):'')+(r.serviceId?row('Manutenção vinculada',esc(r.serviceId),'Resolver esta ocorrência não conclui a manutenção.'):'')+`<div class="actions gap">${r.status==='open'||r.status==='contested'?btn('Iniciar análise','incident-status','primary',`data-id="${r.id}" data-status="analysis"`):''}${r.status!=='resolved'?btn('Ajustar prazo','incident-deadline','',`data-id="${r.id}"`):''}${!r.decision&&['analysis','contested'].includes(r.status)?btn('Registrar decisão','incident-decide','primary',`data-id="${r.id}"`):''}${r.decision&&r.status!=='resolved'?btn('Concluir com parecer','incident-resolve','',`data-id="${r.id}"`):''}</div>${r.decision?panel('Decisão humana preservada',row('Responsável definido',esc(N.responsibilities[r.decision.responsibility]))+row('Valor aprovado',cash(r.decision.approvedAmount))+row('Título vinculado',esc(r.decision.titleId||'Sem movimentação financeira'),'A baixa é feita no Financeiro; resolver não recebe nem paga.')+`<p>${esc(r.decision.reason)}</p><p class="caption">Mensagem ao motorista: ${esc(r.decision.publicNote)}</p>`):''}${r.manifestations.length?panel('O que o motorista informou',r.manifestations.map(m=>`<article class="driver-request"><p>${esc(m.message)}</p><small>${esc(m.requestId)}</small></article>`).join('')):''}<details class="gap"><summary>Histórico completo</summary>${r.history.map(h=>row(esc(h.action),h.visibility==='driver'?'Visível ao motorista':'Interno',esc(h.note))).join('')}</details>`;}
 function incidentDecisionForm(r){return `<form id="incident-decision-form"><input type="hidden" name="incidentId" value="${r.id}"><p class="notice">Decisão humana do exemplo. Atribuir responsabilidade não é automático. Confira contrato, fatos, manifestação, seguro e fundamento antes de criar um compromisso financeiro.</p><div class="fields gap">${select('responsibility','Responsável pelo valor aprovado','',[['','Escolha após análise'],...Object.entries(N.responsibilities)],'required')}${input('approvedAmount','Valor aprovado · R$','','type="number" min="0" step="0.01" required')}${input('counterparty','Quem paga ou recebe · sem documento pessoal','','maxlength="100"')}${input('due','Vencimento do compromisso',r.deadline,'type="date" required')}${input('reference','Referência única da decisão','','required maxlength="100"')}</div><label class="field gap">Fundamento interno da decisão<textarea name="reason" rows="3" required maxlength="1500"></textarea></label><label class="field gap">Explicação simples para o motorista<textarea name="publicNote" rows="3" required maxlength="1000"></textarea></label><label class="check gap"><input name="driverHeard" type="checkbox">O motorista teve oportunidade de se manifestar. Obrigatório se ele for o responsável.</label><label class="check"><input name="insuranceAccepted" type="checkbox">Conferi o aceite da seguradora. Obrigatório se ela for a pagadora.</label><label class="check"><input name="confirmed" type="checkbox" required>Conferi os fatos e o valor. Não haverá retenção de caução nem desconto automático.</label><div class="form-actions"><button class="btn primary" type="submit">Preservar decisão e criar compromisso</button></div></form>`;}
 function driverOccurrencesView(){const records=N.forDriver(ops,activeDriverId);return panel('O que aconteceu com meu carro',records.length?records.map(r=>`<article class="driver-document"><h3>${esc(r.title)}</h3><p>${esc(N.statuses[r.status])} · ${date(r.date)}</p><p>${esc(r.description)}</p><p class="caption">Acompanhamento até ${date(r.deadline)}. Nenhum desconto é feito automaticamente.</p>${r.decision?`<div class="notice"><p>${esc(r.decision.publicNote)}</p>${row('Valor conferido',cash(r.decision.approvedAmount))}${row('Responsável',esc(N.responsibilities[r.decision.responsibility]))}</div>`:'<p>A RODAVOLT está conferindo o que aconteceu. Você pode contar sua versão.</p>'}${r.resolution?`<p>${esc(r.resolution.publicNote)}</p>`:''}${btn('Quero falar sobre isso','incident-manifest','',`data-id="${r.id}"`)}${r.manifestations.length?'<p class="caption">Sua mensagem já foi enviada. A gestão vai acompanhar por aqui.</p>':''}</article>`).join(''):'<p>Nenhuma ocorrência registrada para você.</p>');}
 function incidentAction(action,e){if(!action.startsWith('incident-'))return false;const id=e.dataset.id;if(action==='incident-driver-view'){driverPage='occurrences';close();render();persist();return true;}if(action==='incident-manifest'){const r=N.forDriver(ops,activeDriverId).find(r=>r.id===id);if(!r)throw new RangeError('Esta ocorrência não pertence ao seu perfil.');open('Conte o que aconteceu',`<form id="incident-manifest-form"><input type="hidden" name="incidentId" value="${r.id}"><input type="hidden" name="reference" value="${r.id}-MAN-${r.manifestations.length+1}"><p>${esc(r.title)}</p><label class="field">Sua mensagem<textarea name="message" rows="4" required maxlength="1500" placeholder="Conte sua versão ou tire sua dúvida."></textarea></label><p class="caption gap">Sua mensagem vai para a RODAVOLT. Não envia recurso a órgãos públicos ou à seguradora.</p><div class="form-actions"><button class="btn primary" type="submit">Enviar minha mensagem</button></div></form>`);return true;}if(mode!=='admin')throw new RangeError('A análise da ocorrência é feita pela gestão.');if(action==='incident-new')open('Registrar uma ocorrência',incidentCreateForm());else if(action==='incident-open')open('Acompanhar ocorrência',incidentDetail(id));else if(action==='incident-decide')open('Decisão após análise',incidentDecisionForm(N.lookup(ops,id)));else if(action==='incident-status'||action==='incident-deadline'||action==='incident-resolve'){const r=N.lookup(ops,id),deadline=action==='incident-deadline',resolve=action==='incident-resolve';open(deadline?'Revisar prazo':resolve?'Concluir ocorrência':'Iniciar análise',`<form id="incident-update-form"><input type="hidden" name="incidentId" value="${r.id}"><input type="hidden" name="action" value="${action}"><input type="hidden" name="status" value="${esc(e.dataset.status||'')}">${deadline?input('deadline','Novo prazo',r.deadline,'type="date" required'):''}<label class="field gap">Parecer / motivo<textarea name="note" required rows="3" maxlength="1000"></textarea></label>${resolve?'<label class="field gap">Mensagem simples ao motorista<textarea name="publicNote" required rows="3" maxlength="1000"></textarea></label><label class="check gap"><input name="confirmed" type="checkbox" required>Conferi o caso; cobranças, pagamentos e manutenção continuam em seus próprios registros.</label>':''}<div class="form-actions"><button class="btn primary" type="submit">Salvar acompanhamento</button></div></form>`);}else return false;return true;}
 function incidentSubmit(form,f){if(!form.id.startsWith('incident-'))return false;const id=String(f.get('incidentId')||'');if(form.id==='incident-manifest-form'){N.manifest(ops,id,{driverId:activeDriverId,message:String(f.get('message')),reference:String(f.get('reference'))});close();render();persist();toast('Sua mensagem foi registrada para a RODAVOLT conferir.');return true;}if(mode!=='admin')throw new RangeError('A análise da ocorrência é feita pela gestão.');let createdId=id;if(form.id==='incident-create-form'){const d=M.driver(ops,String(f.get('driverId')));createdId=N.create(ops,{...Object.fromEntries(f.entries()),actor:'management',vehicleId:d.vehicleId,deliveryCycle:d.deliveryCycle||0,unavailable:f.has('unavailable')}).id;}else if(form.id==='incident-decision-form'){N.decide(ops,id,{...Object.fromEntries(f.entries()),actor:'management',confirmed:f.has('confirmed'),driverHeard:f.has('driverHeard'),insuranceAccepted:f.has('insuranceAccepted')});}else if(form.id==='incident-update-form'){const data={...Object.fromEntries(f.entries()),actor:'management',confirmed:f.has('confirmed')};if(f.get('action')==='incident-deadline')N.setDeadline(ops,id,data);else if(f.get('action')==='incident-resolve')N.resolve(ops,id,data);else N.changeStatus(ops,id,data);}else return false;render();persist();open('Acompanhar ocorrência',incidentDetail(createdId));toast('Acompanhamento registrado. Nenhum pagamento ou caução foi movimentado.');return true;}
